package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type LoanRec struct {
	LrAcct      string
	LrPrincipal decimal.Decimal
	LrRate      decimal.Decimal
	LrYears     int64
}

var WsEofFlag string = "N"
var WsInterest decimal.Decimal = decimal.NewFromInt(0)
var WsTotal decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsPrinEd string
var WsIntEd string
var WsTotalEd string

var loanRec LoanRec

var inputLines []string
var inputIdx int = 0

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func parseScaled(s string, scale int32) decimal.Decimal {
	if len(s) == 0 {
		return decimal.NewFromInt(0)
	}
	b := make([]byte, len(s))
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == ' ' {
			b[i] = '0'
		} else {
			b[i] = c
		}
	}
	t := string(b)
	t = strings.TrimSpace(t)
	if t == "" {
		return decimal.NewFromInt(0)
	}
	// t should be digits; if not, treat non-digits as zero where possible
	neg := false
	if len(t) > 0 && (t[0] == '+' || t[0] == '-') {
		if t[0] == '-' {
			neg = true
		}
		t = t[1:]
	}
	// remove any non-digit by treating as zero? just keep digits
	digits := make([]byte, 0, len(t))
	for i := 0; i < len(t); i++ {
		if t[i] >= '0' && t[i] <= '9' {
			digits = append(digits, t[i])
		} else if t[i] == ' ' {
			digits = append(digits, '0')
		} else {
			digits = append(digits, '0')
		}
	}
	if len(digits) == 0 {
		return decimal.NewFromInt(0)
	}
	n, err := strconv.ParseInt(string(digits), 10, 64)
	if err != nil {
		// fallback via decimal
		d, err2 := decimal.NewFromString(string(digits))
		if err2 != nil {
			return decimal.NewFromInt(0)
		}
		d = d.Shift(-scale)
		if neg {
			d = d.Neg()
		}
		return d
	}
	if neg {
		n = -n
	}
	return decimal.New(n, -scale)
}

func parseIntField(s string) int64 {
	if len(s) == 0 {
		return 0
	}
	b := make([]byte, len(s))
	for i := 0; i < len(s); i++ {
		if s[i] == ' ' {
			b[i] = '0'
		} else {
			b[i] = s[i]
		}
	}
	t := string(b)
	t = strings.TrimSpace(t)
	if t == "" {
		return 0
	}
	// keep digits only
	digits := make([]byte, 0, len(t))
	neg := false
	if len(t) > 0 && (t[0] == '+' || t[0] == '-') {
		if t[0] == '-' {
			neg = true
		}
		t = t[1:]
	}
	for i := 0; i < len(t); i++ {
		if t[i] >= '0' && t[i] <= '9' {
			digits = append(digits, t[i])
		} else {
			digits = append(digits, '0')
		}
	}
	if len(digits) == 0 {
		return 0
	}
	n, err := strconv.ParseInt(string(digits), 10, 64)
	if err != nil {
		return 0
	}
	if neg {
		n = -n
	}
	return n
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func parseLoanLine(line string) LoanRec {
	// line already stripped of \n and \r, keep spaces otherwise
	// operate on bytes
	if len(line) > 21 {
		line = line[:21]
	}
	if len(line) < 21 {
		line = line + strings.Repeat(" ", 21-len(line))
	}
	acct := line[0:6]
	prStr := line[6:15]
	rateStr := line[15:19]
	yearsStr := line[19:21]
	return LoanRec{
		LrAcct:      acct,
		LrPrincipal: parseScaled(prStr, 2),
		LrRate:      parseScaled(rateStr, 2),
		LrYears:     parseIntField(yearsStr),
	}
}

func storeMod(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// assume v already rounded/truncated to scale
	scaled := v.Shift(scale).IntPart()
	mod := int64(1)
	for i := 0; i < intDigits+int(scale); i++ {
		mod *= 10
	}
	// mod fits in int64 for our uses (max 1e13)
	scaled = scaled % mod
	if scaled < 0 {
		scaled += mod
	}
	return decimal.New(scaled, -scale)
}

func formatEdited(val decimal.Decimal, pic string) string {
	// split picture at '.'
	dotPos := strings.Index(pic, ".")
	var intPic, fracPic string
	if dotPos >= 0 {
		intPic = pic[:dotPos]
		fracPic = pic[dotPos+1:]
	} else {
		intPic = pic
		fracPic = ""
	}
	// count placeholders
	intSlots := 0
	for i := 0; i < len(intPic); i++ {
		if intPic[i] == 'Z' || intPic[i] == '9' {
			intSlots++
		}
	}
	fracSlots := 0
	for i := 0; i < len(fracPic); i++ {
		if fracPic[i] == 'Z' || fracPic[i] == '9' {
			fracSlots++
		}
	}
	neg := val.IsNegative()
	if neg {
		val = val.Neg()
	}
	// truncate toward zero to fracSlots (MOVE semantics; scales equal here)
	val = val.Truncate(int32(fracSlots))
	intPart := val.IntPart()
	fracPart := val.Sub(decimal.New(intPart, 0))
	// fractional digits
	fracDigits := ""
	if fracSlots > 0 {
		scaledFrac := fracPart.Shift(int32(fracSlots)).IntPart()
		if scaledFrac < 0 {
			scaledFrac = -scaledFrac
		}
		fs := strconv.FormatInt(scaledFrac, 10)
		if len(fs) < fracSlots {
			fs = strings.Repeat("0", fracSlots-len(fs)) + fs
		} else if len(fs) > fracSlots {
			fs = fs[len(fs)-fracSlots:]
		}
		fracDigits = fs
	}
	// integer digits string
	intStr := strconv.FormatInt(intPart, 10)
	if len(intStr) < intSlots {
		intStr = strings.Repeat("0", intSlots-len(intStr)) + intStr
	} else if len(intStr) > intSlots {
		intStr = intStr[len(intStr)-intSlots:]
	}
	// find first non-zero
	firstNZ := intSlots // none
	for i := 0; i < intSlots; i++ {
		if intStr[i] != '0' {
			firstNZ = i
			break
		}
	}
	if firstNZ == intSlots {
		firstNZ = intSlots - 1 // keep last zero
	}
	// map digits to picture
	var out strings.Builder
	digitIdx := 0
	for i := 0; i < len(intPic); i++ {
		c := intPic[i]
		if c == 'Z' || c == '9' {
			d := intStr[digitIdx]
			if digitIdx < firstNZ {
				// suppressed
				out.WriteByte(' ')
			} else {
				out.WriteByte(d)
			}
			digitIdx++
		} else if c == ',' {
			// comma: space if everything to left suppressed
			if digitIdx <= firstNZ {
				out.WriteByte(' ')
			} else {
				out.WriteByte(',')
			}
		} else {
			out.WriteByte(c)
		}
	}
	if dotPos >= 0 {
		out.WriteByte('.')
		// fracPic assumed all 9s
		out.WriteString(fracDigits)
	}
	_ = neg
	return out.String()
}

func loadInput() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		inputLines = []string{}
		return
	}
	s := string(data)
	parts := strings.Split(s, "\n")
	// drop trailing element from final newline
	if len(parts) > 0 && s[len(s)-1:] == "\n" {
		parts = parts[:len(parts)-1]
	}
	// strip trailing \r
	for i, p := range parts {
		if len(p) > 0 && p[len(p)-1] == '\r' {
			parts[i] = p[:len(p)-1]
		}
	}
	// handle empty file: Split("") returns [""] -> should be zero records
	if len(parts) == 1 && parts[0] == "" && len(data) == 0 {
		inputLines = []string{}
		return
	}
	inputLines = parts
}

func READPARA() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	loanRec = parseLoanLine(line)
}

func PROCESSPARA() {
	tmp := loanRec.LrPrincipal.Mul(loanRec.LrRate).Mul(decimal.NewFromInt(loanRec.LrYears)).Shift(-2)
	rounded := tmp.Round(2)
	WsInterest = storeMod(rounded, 9, 2)
	WsTotal = storeMod(WsTotal.Add(WsInterest), 11, 2)
	WsCount = (WsCount + 1) % 100000
	WsPrinEd = formatEdited(loanRec.LrPrincipal, "Z,ZZZ,ZZ9.99")
	WsIntEd = formatEdited(WsInterest, "ZZZ,ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s\n", loanRec.LrAcct, WsPrinEd, WsIntEd)
	READPARA()
}

func SUMMARYPARA() {
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%05d", WsCount)
	fmt.Printf("RECORDS: %s\n", countStr)
	fmt.Printf("TOTAL INTEREST: %s\n", WsTotalEd)
}

func main() {
	loadInput()
	inputIdx = 0
	WsEofFlag = "N"
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	SUMMARYPARA()
}
